// Debounce function
function debounce(func, wait) {
    let timeoutId;
    return function() {
        const context = this;
        const args = arguments;
        clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
            func.apply(context, args);
        }, wait);
    };
}

// Example usage:
function myFunction() {
    console.log('Hello, World!');
}

const debouncedMyFunction = debounce(myFunction, 500);

// Call the debounced function
debouncedMyFunction();

